// Turn the claimed rows into one JSON response for the worker.
// The Postgres node has alwaysOutputData ON, so when the queue is empty we
// still get one empty item here and must answer {"records": []} - never hang.
const records = $input.all()
  .map(item => item.json)
  .filter(r => r && r.id !== undefined && r.id !== null)
  .map(r => ({
    id: r.id,
    rss_id: r.rss_id,
    title: r.title,
    date: r.date,
    url: r.url,
  }));

return [{ json: { records, count: records.length } }];

// Validate + normalise what the worker posted back, so a buggy client can
// never push junk into the database.
const body = $input.first().json.body || {};

const MAX_CHARS = 10000;   // keep in sync with MAX_CONTENT_CHARS in the notebook
const MIN_CHARS = 150;     // keep in sync with MIN_CONTENT_CHARS in the notebook

const nodeName = String(body.node_name || 'unknown-worker').slice(0, 100);
const raw = Array.isArray(body.results) ? body.results : [];

const results = [];
const seen = new Set();

for (const r of raw) {
  const id = Number(r && r.id);
  if (!Number.isFinite(id) || seen.has(id)) continue;
  seen.add(id);

  // accept both {content: ...} and {text: ...}
  let content = typeof r.content === 'string'
    ? r.content
    : (typeof r.text === 'string' ? r.text : '');

  // Postgres text columns cannot hold NUL bytes
  content = content.replace(/\u0000/g, '').trim().slice(0, MAX_CHARS);

  const ok = r.status === 'content' && content.length >= MIN_CHARS;

  results.push({
    id,
    status: ok ? 'content' : 'error',
    content: ok ? content : null,
    error: ok ? null : String(r.error || `too short (${content.length} chars)`).slice(0, 300),
  });
}

return [{ json: { node_name: nodeName, results, received: raw.length } }];

// Flatten the heartbeat into the 4 columns worker_status needs.
const body = $input.first().json.body || {};

return [{
  json: {
    node_name:   String(body.node_name || 'unknown-worker').slice(0, 100),
    worker_type: String(body.worker_type || 'content-extractor').slice(0, 50),
    status:      String(body.status || 'running').slice(0, 30),
    payload:     JSON.stringify(body),
  },
}];
